const express = require('express');
const helmet = require('helmet');

const app = express();

// Method 1: Use helmet (recommended - includes X-Content-Type-Options by default)
app.use(helmet());

// Method 2: Use specific helmet middleware
app.use(helmet.noSniff());

// Method 3: Manual middleware (if not using helmet)
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  next();
});

// Method 4: Helmet with custom security headers
app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
      },
    },
    xContentTypeOptions: true,  // Explicitly enable (default)
    xFrameOptions: { action: 'deny' },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
    },
  })
);

app.get('/', (req, res) => {
  res.send('<h1>Protected from MIME sniffing</h1>');
});

app.get('/api/data', (req, res) => {
  res.json({ message: 'API response with nosniff header' });
});

