const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('X-Content-Type-Options Header Tests', () => {
  it('should have X-Content-Type-Options header', (done) => {
    request(app)
      .get('/')
      .expect(200)
      .expect('X-Content-Type-Options', 'nosniff')
      .end(done);
  });

  it('should have nosniff value only', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const xcto = res.headers['x-content-type-options'];
        expect(xcto).to.equal('nosniff');

        done();
      });
  });

  it('should protect all routes', (done) => {
    const routes = ['/', '/api/data', '/static/style.css'];
    let completed = 0;

    routes.forEach(route => {
      request(app)
        .get(route)
        .end((err, res) => {
          if (!err) {
            expect(res.headers['x-content-type-options']).to.equal('nosniff');
          }
          completed++;
          if (completed === routes.length) done();
        });
    });
  });

  it('should work with different content types', (done) => {
    request(app)
      .get('/api/data')
      .expect('Content-Type', /json/)
      .expect('X-Content-Type-Options', 'nosniff')
      .end(done);
  });
});

