    public XContentTypeOptionsTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Should_Have_XContentTypeOptions_Header()
    {
        var response = await _client.GetAsync("/");

        Assert.True(response.Headers.Contains("X-Content-Type-Options"),
            "Response should contain X-Content-Type-Options header");
    }

    [Fact]
    public async Task XContentTypeOptions_Should_Be_NoSniff()
    {
        var response = await _client.GetAsync("/");
        var header = response.Headers.GetValues("X-Content-Type-Options").First();

        Assert.Equal("nosniff", header);
    }

    [Theory]
    [InlineData("/")]
    [InlineData("/Home/Index")]
    [InlineData("/api/data")]
    public async Task All_Endpoints_Should_Have_Header(string path)
    {
        var response = await _client.GetAsync(path);

        Assert.True(response.Headers.Contains("X-Content-Type-Options"),
            $"Endpoint {path} should have X-Content-Type-Options header");

        var header = response.Headers.GetValues("X-Content-Type-Options").First();
        Assert.Equal("nosniff", header);
    }

    [Fact]
    public async Task Should_Work_With_Different_Content_Types()
    {
        // Test HTML page
        var htmlResponse = await _client.GetAsync("/");
        Assert.Contains("X-Content-Type-Options", 
            htmlResponse.Headers.Select(h => h.Key));

        // Test JSON API
        var jsonResponse = await _client.GetAsync("/api/data");
        Assert.Contains("X-Content-Type-Options", 
            jsonResponse.Headers.Select(h => h.Key));
    }
}

