def test_xcontent_type_options_header_present(client):
    """Test that X-Content-Type-Options header is present"""
    response = client.get('/')

    assert 'X-Content-Type-Options' in response.headers, \
        "Response should contain X-Content-Type-Options header"

@pytest.mark.django_db
def test_xcontent_type_options_nosniff(client):
    """Test that X-Content-Type-Options is set to nosniff"""
    response = client.get('/')
    xcto = response.headers.get('X-Content-Type-Options', '')

    assert xcto == 'nosniff', \
        f"X-Content-Type-Options should be nosniff, got: {xcto}"

@pytest.mark.django_db
def test_all_pages_protected(client):
    """Test that all pages have X-Content-Type-Options header"""
    test_urls = ['/', '/login/', '/api/data/', '/static/style.css']

    for url in test_urls:
        response = client.get(url)
        assert 'X-Content-Type-Options' in response.headers, \
            f"Page {url} should have X-Content-Type-Options header"
        assert response.headers['X-Content-Type-Options'] == 'nosniff'

