# Nginx - Add X-Content-Type-Options header
# /etc/nginx/sites-available/your-site or /etc/nginx/nginx.conf

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name your-domain.com;

    # Add X-Content-Type-Options header
    add_header X-Content-Type-Options "nosniff" always;

    # Other recommended security headers
    add_header X-Frame-Options "DENY" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Content-Security-Policy "default-src 'self'" always;

    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Ensure header on static files too
    location ~* \.(css|js|jpg|jpeg|png|gif|ico|svg|woff|woff2|ttf)$ {
        add_header X-Content-Type-Options "nosniff" always;
        expires 1y;
        access_log off;
    }
}

# Note: 'always' ensures header added even for error responses

