// Selenium test for X-Content-Type-Options validation
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.logging.LogEntries;
import org.openqa.selenium.logging.LogEntry;
import org.openqa.selenium.logging.LogType;
import org.testng.annotations.Test;
import org.testng.Assert;

public class XContentTypeOptionsTest {

    @Test
    public void verifyXContentTypeOptionsPresent() {
        ChromeOptions options = new ChromeOptions();
        options.setCapability("goog:loggingPrefs", 
            Map.of("performance", "ALL"));

        WebDriver driver = new ChromeDriver(options);

        try {
            driver.get("https://your-domain.com");

            // Get performance logs to check headers
            LogEntries logs = driver.manage().logs().get(LogType.PERFORMANCE);

            boolean headerFound = false;
            for (LogEntry entry : logs) {
                String message = entry.getMessage();
                if (message.contains("X-Content-Type-Options") && 
                    message.contains("nosniff")) {
                    headerFound = true;
                    break;
                }
            }

            Assert.assertTrue(headerFound, 
                "X-Content-Type-Options: nosniff header should be present");

        } finally {
            driver.quit();
        }
    }

    @Test
    public void verifyAllResourceTypesProtected() {
        WebDriver driver = new ChromeDriver();

        String[] resources = {
            "https://your-domain.com/",           // HTML
            "https://your-domain.com/style.css",  // CSS
            "https://your-domain.com/script.js",  // JS
            "https://your-domain.com/api/data"    // JSON
        };

        try {
            for (String resource : resources) {
                // Use REST Assured or HTTP client to check headers
                // (Selenium doesn't directly expose response headers)
                System.out.println("Checking: " + resource);
                // Validation logic here
            }
        } finally {
            driver.quit();
        }
    }

    @Test
    public void verifyNoContentTypeMismatchErrors() {
        WebDriver driver = new ChromeDriver();

        try {
            driver.get("https://your-domain.com");

            // Get browser console logs
            LogEntries logs = driver.manage().logs().get(LogType.BROWSER);

            for (LogEntry entry : logs) {
                String message = entry.getMessage();
                // Check for MIME type mismatch errors
                Assert.assertFalse(
                    message.contains("MIME type") && message.contains("mismatch"),
                    "Should not have MIME type mismatch errors: " + message
                );
            }
        } finally {
            driver.quit();
        }
    }
}
